cd /tmp && python3 -c "
import html.parser, re

class TextExtract(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = 0
        self.in_pre = False
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style','nav','footer','header'):
            self.skip += 1
        if tag == 'pre':
            self.in_pre = True
            self.parts.append('\n\`\`\`\n')
        if tag in ('p','div','h1','h2','h3','h4','li','br','tr'):
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script','style','nav','footer','header'):
            self.skip -= 1
        if tag == 'pre':
            self.in_pre = False
            self.parts.append('\n\`\`\`\n')
        if tag in ('p','h1','h2','h3','h4','li'):
            self.parts.append('\n')
    def handle_data(self, data):
        if self.skip <= 0:
            self.parts.append(data)

p = TextExtract()
p.feed(open('/tmp/statem.html').read())
text = ''.join(p.parts)
text = re.sub(r'\n{3,}', '\n\n', text)
open('/tmp/statem.txt','w').write(text)
print(len(text))
"

