function revDate(r: string): string {
  try { return execFileSync("git", ["log", "-1", "--format=%ai", r], { cwd: MIND, encoding: "utf8" }).trim().slice(0, 10); }
  catch { return "unknown"; }
}
function shortRev(r: string): string { return r.slice(0, 7); }

const lines: string[] = [];
lines.push("---");
lines.push("date: 2026-07-28");
lines.push("session: 00000000-0000-4000-8000-000000000e2e");
lines.push("arc: Genesis Archaeology");
lines.push("---");
lines.push("");
lines.push(
  "This is not a live session transcript — it is an authored archaeology episode " +
  "(popmem WS-E2/E3, GATE 2 ruling OPTION (a) + WS-E3 fix B): the founding tellings of " +
  "every live SELF.md entry that migrate.ts could not otherwise trace to a real episode — " +
  "the 25 zero-[ep:]-stamp entries (identity, motifs, unstamped how-we-work) that predate " +
  "the [ep:] stamp convention entirely (the mind's founding archaeology import from " +
  "pre-Circadian shards, mind git history, earliest around commit 6d31278, 2026-07-16), " +
  "PLUS 4 doctrine entries whose own dated episode citation doesn't literally contain their " +
  "claim (WS-E3: splitting the WS-E stutter megacluster removed the verbatim quote each of " +
  "these borrowed from Doctrine[1]). Each telling below is copied VERBATIM from the earliest " +
  "mind git revision that carries it (git show <rev>:SELF.md), attributed by short revision " +
  "and commit date, so the counterfeit-quote assert (stack.ts quotesAreVerbatim) has a real, " +
  "checkable, non-fabricated source instead of an unverifiable founding claim. migrate.ts " +
  "seeds this file into the sandbox's mind/episodes/ (never the live mind directly — WS-F's " +
  "gated commit places the real one)."
);
lines.push("");

lines.push("## Identity");
lines.push("");
for (const i of identity) {
  const e = earliestIdentity(history, normalizeQuoteKey(i.text));
  lines.push(`mind@${shortRev(e.rev)} (${revDate(e.rev)}): ${e.entry.text}`);
  lines.push("");
}

lines.push("## Motifs");
lines.push("");
for (const m of motifs) {
  const e = earliestBullet(history, normalizeLineKey(m.line), (d) => d.motifs);
  lines.push(`mind@${shortRev(e.rev)} (${revDate(e.rev)}): ${e.entry.line}`);
  lines.push("");
}

lines.push("## How we work");
lines.push("");
for (const b of how) {
  if (b.eps.length > 0) continue; // "Show, never describe" already has a real episode source
  const e = earliestBullet(history, normalizeLineKey(b.line), (d) => d.howWeWork);
  lines.push(`mind@${shortRev(e.rev)} (${revDate(e.rev)}): ${e.entry.line}`);
  lines.push("");
}

lines.push("## Doctrine (residual, WS-E3 fix B — earliest clean telling, title + why-chain verbatim)");
lines.push("");
const residualGroupKeys = ["5", "7", "8,12,16", "13,17"];
for (const group of clustering.groups) {
  const key = [...group].sort((a, b) => a - b).join(",");
