    const db = b.earliest.entry?.eps[0] ?? "9999-99-99";
    return da < db ? -1 : da > db ? 1 : a.m.n - b.m.n;
  });
  const winner = tellings[0];
  lines.push(`mind@${shortRev(winner.earliest.rev)} (${revDate(winner.earliest.rev)}), Doctrine[${key}] earliest telling: ${winner.earliest.entry.title} ${winner.earliest.entry.body}`);
  lines.push("");
}

lines.push("taught -> absorbed-where: this archaeology becomes the source episode for 25 seed atoms (identity, motif, agreement kinds) plus 4 residual doctrine atoms in the popmem migration — see docs/POPMEM-MIGRATION-REVIEW.md.");
lines.push("");

const out = lines.join("\n");
fs.writeFileSync("docs/genesis-archaeology.episode.md", out);
console.log("wrote", out.length, "chars, ~", Math.ceil(out.length / 4), "tokens");
EOF
